from dataclasses import dataclass
from datetime import datetime
from typing import Any

from packaging.specifiers import InvalidSpecifier, SpecifierSet
from packaging.version import InvalidVersion, Version


def _parse_upload_time(value: Any) -> datetime | None:
    """Parse a PyPI ``upload_time_iso_8601`` string into a ``datetime``.

    Returns ``None`` if the value is missing or cannot be parsed.
    """
    if not isinstance(value, str) or not value:
        return None
    try:
        # ``datetime.fromisoformat`` in older Python versions does not accept a
        # trailing ``Z``, so normalize it to an explicit UTC offset.
        return datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None


@dataclass
class Release:
    """A single package release (one version) with its distributions collapsed."""

    version: Version
    upload_time: datetime
    yanked: bool
    requires_python: SpecifierSet | None

    @classmethod
    def from_distributions(
        cls, version: Version, distributions: list[dict[str, Any]]
    ) -> Release | None:
        """Build a ``Release`` from the list of distributions for a version.

        Returns ``None`` if no distribution has a parseable upload time.
        """
        upload_times = [
            t
            for d in distributions
            if (t := _parse_upload_time(d.get("upload_time_iso_8601"))) is not None
        ]
        if not upload_times:
            return None

        # A release is yanked only if every one of its distributions is yanked.
        yanked = all(bool(d.get("yanked")) for d in distributions)

        # Use the first non-empty, valid ``requires_python`` across distributions.
        requires_python: SpecifierSet | None = None
        for d in distributions:
            raw = d.get("requires_python")
            if not raw:
                continue
            try:
                requires_python = SpecifierSet(raw)
            except InvalidSpecifier:
                continue
            break

        return cls(
            version=version,
            upload_time=min(upload_times),
            yanked=yanked,
            requires_python=requires_python,
        )


@dataclass
class Package:
    """Typed representation of a PyPI package and its releases."""

    name: str
    releases: dict[Version, Release]

    @classmethod
    def from_json(cls, data: dict[str, Any]) -> Package:
        info = data.get("info") or {}
        name = info.get("name") or data.get("name") or ""

        releases: dict[Version, Release] = {}
        for version_str, distributions in (data.get("releases") or {}).items():
            # Drop releases with no distributions.
            if not distributions:
                continue
            # Drop releases whose version string is not a valid PEP 440 version.
            try:
                version = Version(version_str)
            except InvalidVersion:
                continue
            # Drop releases where no distribution has a parseable upload time.
            release = Release.from_distributions(version, distributions)
            if release is None:
                continue
            releases[version] = release

        return cls(name=name, releases=releases)

    @property
    def versions(self) -> tuple[Version, ...]:
        return tuple(sorted(self.releases))

    @property
    def latest_version(self) -> Version | None:
        candidates = [
            version
            for version in sorted(self.releases)
            if not version.is_prerelease
            and not version.is_devrelease
            and not self.releases[version].yanked
        ]
        return candidates[-1] if candidates else None

    def get_release(self, version: str | Version) -> Release | None:
        if isinstance(version, str):
            try:
                version = Version(version)
            except InvalidVersion:
                return None
        return self.releases.get(version)
